"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[44816],{3331:(e,r,t)=>{t.d(r,{R:()=>a,x:()=>o});var n=t(36672);const i={},s=n.createContext(i);function a(e){const r=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),n.createElement(s.Provider,{value:r},e.children)}},8711:(e,r,t)=>{t.r(r),t.d(r,{assets:()=>d,contentTitle:()=>o,default:()=>m,frontMatter:()=>a,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"2023/04/13","title":"2023-04-13","description":"Semafore: Et tastatur til hele kroppen","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/13.md","sourceDirName":"2023/04","slug":"/2023/04/13","permalink":"/da/2023/04/13","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/13.md","tags":[],"version":"current","frontMatter":{"localized_date":"13. april 2023","top_news":"Semafore: Et tastatur til hele kroppen"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-14","permalink":"/da/2023/04/14"},"next":{"title":"2023-04-12","permalink":"/da/2023/04/12"}}');var i=t(23420),s=t(3331);const a={localized_date:"13. april 2023",top_news:"Semafore: Et tastatur til hele kroppen"},o="2023-04-13",d={},l=[{value:"Semafore: Et tastatur til hele kroppen",id:"semafore-et-tastatur-til-hele-kroppen",level:2},{value:"Vis GPT-4-drevne web-s\xf8gninger for udviklere",id:"vis-gpt-4-drevne-web-s\xf8gninger-for-udviklere",level:2},{value:"Erstatning af mine bedste venner med en LLM tr\xe6net p\xe5 500k gruppechatbeskeder",id:"erstatning-af-mine-bedste-venner-med-en-llm-tr\xe6net-p\xe5-500k-gruppechatbeskeder",level:2},{value:"NPR forlader Twitter efter at v\xe6re blevet stemplet som &quot;statstilknyttede medier",id:"npr-forlader-twitter-efter-at-v\xe6re-blevet-stemplet-som-statstilknyttede-medier",level:2},{value:"Massefyringer og frav\xe6rende chefer skaber moralsk krise hos Meta",id:"massefyringer-og-frav\xe6rende-chefer-skaber-moralsk-krise-hos-meta",level:2},{value:"Hetzner introducerer ARM64 cloud-servere",id:"hetzner-introducerer-arm64-cloud-servere",level:2},{value:"Ny NASA-direkt\xf8r sv\xe6rger ed p\xe5 Carl Sagans &quot;Pale Blue Dot&quot; i stedet for p\xe5 Bibelen",id:"ny-nasa-direkt\xf8r-sv\xe6rger-ed-p\xe5-carl-sagans-pale-blue-dot-i-stedet-for-p\xe5-bibelen",level:2},{value:"Intel Foundry Services og Arm annoncerer samarbejde om SoC-design",id:"intel-foundry-services-og-arm-annoncerer-samarbejde-om-soc-design",level:2},{value:"EVE Online-spiller bruger obskur regel til at gennemf\xf8re det st\xf8rste kup i spillets historie",id:"eve-online-spiller-bruger-obskur-regel-til-at-gennemf\xf8re-det-st\xf8rste-kup-i-spillets-historie",level:2},{value:"Virtuelle tr\xe5de ankommer i JDK 21 og indleder en ny \xe6ra for concurrency",id:"virtuelle-tr\xe5de-ankommer-i-jdk-21-og-indleder-en-ny-\xe6ra-for-concurrency",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-13",children:"2023-04-13"})}),"\n",(0,i.jsx)(r.h2,{id:"semafore-et-tastatur-til-hele-kroppen",children:"Semafore: Et tastatur til hele kroppen"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/everythingishacked/Semaphore",children:"Original"}),'.\nSemaphore er et helkrops-tastatur, der bruger OpenCV og MediaPipes posedetektion til at registrere kropsm\xe6rker fra videoinput, beregne relative forskelle og overs\xe6tte dem til taster og kommandoer, der sendes via tastaturet. Det prim\xe6re input er at "skrive" bogstaver, cifre og symboler via flag semaphore ved at str\xe6kke begge arme i forskellige vinkler, med andre modificerende bev\xe6gelser inkluderet for funktioner som shift, backspace og piletaster. Det k\xf8rer p\xe5 den nyeste MacOS og kan tilg\xe5s via terminalen ved hj\xe6lp af et brugerdefineret tastaturbibliotek.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35536550",children:"Discussion Service"}),".\nEt tastatursystem kaldet Semaphore, som anvender fysiske bev\xe6gelser, har f\xe5et positive tilbagemeldinger fra Discussion Service-brugere og har betydning for fjernarbejdere, som \xf8nsker at kombinere fysisk tr\xe6ning og programmering. Brugerne diskuterer at kombinere Semaphore med stenografi, musikalske noter, yoga\xf8velser og programmering, og nogle p\xe5peger potentialet for \xf8get effektivitet gennem tilf\xf8jelse af funktioner som f.eks. autokomplettering."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-gpt-4-drevne-web-s\xf8gninger-for-udviklere",children:"Vis GPT-4-drevne web-s\xf8gninger for udviklere"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.phind.com",children:"Original"}),'.\nWebstedet "phind.com" er i \xf8jeblikket utilg\xe6ngeligt, da det bruger en sikkerhedstjeneste til at beskytte sig mod onlineangreb, som kan v\xe6re udl\xf8st af visse handlinger, f.eks. indsendelse af et bestemt ord eller en bestemt s\xe6tning, en SQL-kommando eller misdannede data. For at l\xf8se dette problem kan brugerne sende en e-mail til ejeren af webstedet med oplysninger om, hvad de gjorde, da blokaden opstod, og det Cloudflare Ray ID, der findes nederst p\xe5 siden.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35543668",children:"Discussion Service"}),".\nPhind.com's GPT-4-drevne s\xf8gemaskine tilbyder pr\xe6cise kodningssvar og detaljerede forklaringer gennem brugerdefinerede filtre, og der er blevet unders\xf8gt indkomstdelingsmodeller for indholdsproducenter, selv om der er bekymring over modelleringsomkostningerne; brugerne har rost tjenesten for dens klare oplysninger, effektivitet og v\xe6rdifulde supplerende oplysninger, selv om der er blevet bem\xe6rket nogle problemer med foresp\xf8rgselsn\xf8jagtigheden. Nogle brugere har kritiseret GPT-4's evne til at l\xf8se problemer og har sat sp\xf8rgsm\xe5lstegn ved dens n\xf8jagtighed og relevans, men Phind-teamet har reageret ved at frigive en ny version med en ekspertfunktion."]}),"\n",(0,i.jsx)(r.h2,{id:"erstatning-af-mine-bedste-venner-med-en-llm-tr\xe6net-p\xe5-500k-gruppechatbeskeder",children:"Erstatning af mine bedste venner med en LLM tr\xe6net p\xe5 500k gruppechatbeskeder"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.izzy.co/blogs/robo-boys.html",children:"Original"}),".\nEn LLM blev tr\xe6net p\xe5 Izzy Millers ucensurerede gruppechatbeskeder fra collegetiden, hvilket resulterede i bedre samtaler med hans bedste venner. Datas\xe6ttet bestod af 500k beskeder, og Miller sessionerede det for at g\xf8re det lettere at modellere. Den resulterende model genererede hele samtaler og fangede den kontekstuelle essens af gruppechatten, og artiklen forklarer, hvordan man konverterer LLaMA-v\xe6gte til et format, der er kompatibelt med Transformers-biblioteket ved hj\xe6lp af Python-kodning, herunder vigtigheden af korrekt tilr\xe5dighedsstillelse af diskplads."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35540154",children:"Discussion Service"}),".\nNogle Discussion Service-brugere udtrykker bekymring over de etiske konsekvenser af at skabe digitale kopier af enkeltpersoner ved hj\xe6lp af personlige data, mens andre h\xe6vder, at eksisterende love og moralsk/socialt pres stadig g\xe6lder. Kritikere advarer om potentielle skadelige anvendelser af LLM-teknologien af autokratiske regimer eller til profitorienterede form\xe5l. Der er opst\xe5et splittede debatter om AI-teknologi med bekymringer om dens upr\xf8vede indvirkning p\xe5 privatlivets fred og en overdreven skepsis over for dens effektivitet. Der er kontroverser omkring brugen af AI-chatbots og deres potentiale til at erstatte menneskelige forbindelser samt etiske bet\xe6nkeligheder ved v\xe6rkt\xf8jer til tekstudfyldning, der g\xf8r det muligt at skabe digitale simuleringer af tabte k\xe6re."]}),"\n",(0,i.jsx)(r.h2,{id:"npr-forlader-twitter-efter-at-v\xe6re-blevet-stemplet-som-statstilknyttede-medier",children:'NPR forlader Twitter efter at v\xe6re blevet stemplet som "statstilknyttede medier'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.wbur.org/npr/1169269161/npr-leaves-twitter-government-funded-media-label",children:"Original"}),'.\nNPR stoppede sin Twitter-aktivitet, efter at Twitter havde betegnet dem som "statstilknyttede medier", en betegnelse, som NPR mener er un\xf8jagtig og vildledende. Denne beslutning beskytter NPR\'s trov\xe6rdighed og sikrer, at de kan producere journalistik uden negativitet. Elon Musk indr\xf8mmede, at han m\xe5ske har taget fejl med etiketten og m\xe5ske \xe6ndrer den til "offentligt finansieret".']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35539280",children:"Discussion Service"}),'.\nNPR blev udsat for kritik og forlod i sidste ende Twitter efter at v\xe6re blevet betegnet som "statstilknyttede medier" p\xe5 grund af statslig finansiering, hvilket f\xf8rte til en debat om kriterierne for en s\xe5dan betegnelse, og om den pr\xe6cist karakteriserer NPR som en nyhedsorganisation med redaktionel uafh\xe6ngighed. Nogle Discussion Service-brugere foresl\xe5r, at andre virksomheder, herunder Elon Musks firmaer, falder ind under denne kategori p\xe5 grund af statslig finansiering. Kommentarerne fremh\xe6ver ogs\xe5 det komplekse forhold mellem medier, finansieringskilder og redaktionel uafh\xe6ngighed, idet nogle beskylder NPR for venstreorienteret partiskhed, mens andre forsvarer dets gennemsigtighed og uafh\xe6ngighed.']}),"\n",(0,i.jsx)(r.h2,{id:"massefyringer-og-frav\xe6rende-chefer-skaber-moralsk-krise-hos-meta",children:"Massefyringer og frav\xe6rende chefer skaber moralsk krise hos Meta"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html",children:"Original"}),".\nMoralen er dalet i Facebooks moderselskab Meta p\xe5 grund af massefyringer og frav\xe6rende chefer, der skaber bekymring blandt medarbejderne. Medarbejderne s\xe6tter ogs\xe5 sp\xf8rgsm\xe5lstegn ved selskabets retning."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35537813",children:"Discussion Service"}),".\nEksperter diskuterer forskellige holdninger til fremtiden for banebrydende teknologier som generativ AI, VR og kryptovaluta. Mens nogle g\xe5r ind for specifikke anvendelsestilf\xe6lde af generativ AI og fremskridt inden for generative medier, rejses der bekymringer om dens potentiale til at automatisere job i middelklassen og om n\xf8jagtigheden af generative AI-modeller. Virksomhederne ser p\xe5 generativ AI for at hj\xe6lpe med at fremskynde markedet for AR/VR-teknologi, og Meta Labs' enheders succes st\xe5r i kontrast til den usikre succes for Apples headset. Kryptoindustrien betragtes af nogle som en affinitetsfidus, men Bitcoin opfattes stadig anderledes af andre."]}),"\n",(0,i.jsx)(r.h2,{id:"hetzner-introducerer-arm64-cloud-servere",children:"Hetzner introducerer ARM64 cloud-servere"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.hetzner.com/press-release/arm64-cloud/",children:"Original"}),".\nDen tyske hosting- og cloud-udbyder Hetzner har lanceret fire nye Hetzner Cloud-servere baseret p\xe5 Arm64-teknologi, hvilket markerer virksomhedens f\xf8rste brug af processorer. Serverne tilbyder op til 16 vCPU'er og kombineres med op til 32 GB ECC RAM og op til 320 GB NVMe SSD-baseret lagringsplads. Den nye serie af servere starter ved en pris p\xe5 3,79 \u20ac (4,54 $) pr. m\xe5ned og har timebaseret faktureringsmuligheder, der vil s\xe6nke omkostningerne for kunderne."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35540084",children:"Discussion Service"}),".\nHetzner har lanceret ARM64 cloud-servere, der er billigere og bedre end AWS. Cloud-infrastruktur har blandede meninger, da nogle argumenterer for p\xe5lidelighed og skalerbarhed, mens andre finder enklere ops\xe6tninger mere p\xe5lidelige og omkostningseffektive. Hetzners tilbud udfylder et hul for dem, der \xf8nsker at k\xf8re Docker uden at konfigurere alle tjenesterne, men det er m\xe5ske ikke egnet til sikkerhedsbevidste virksomheder p\xe5 grund af den svagere fysiske adgangskontrol. Nogle har rapporteret om kontoforbud p\xe5 grund af Hetzners strenge svindelpolitik, og der er sp\xf8rgsm\xe5l om b\xe6redygtigheden af den lave prisfasts\xe6ttelse i Europa p\xe5 grund af h\xf8je energiomkostninger."]}),"\n",(0,i.jsx)(r.h2,{id:"ny-nasa-direkt\xf8r-sv\xe6rger-ed-p\xe5-carl-sagans-pale-blue-dot-i-stedet-for-p\xe5-bibelen",children:'Ny NASA-direkt\xf8r sv\xe6rger ed p\xe5 Carl Sagans "Pale Blue Dot" i stedet for p\xe5 Bibelen'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.independent.co.uk/space/nasa-director-carl-sagan-oath-b2317698.html",children:"Original"}),'.\nMakenzie Lystrup, den nyudn\xe6vnte direkt\xf8r for NASA\'s Goddard Space Flight Center, har aflagt en utraditionel ed ved at bruge Carl Sagans bog "Pale Blue Dot" fra 1994 i stedet for Bibelen. Astronomens bog var inspireret af det ber\xf8mte Pale Blue Dot-foto af Jorden, der blev taget i 1990 af rumsonden Voyager 1, og Lystrup h\xe6vder, at hun er "st\xe6rkt fokuseret p\xe5 at f\xe5 den n\xe6ste generation af innovatorer til at vokse". Goddard Space Flight Centers arbejdsstyrke best\xe5r af 10.000 ansatte, b\xe5de tjenestem\xe6nd og kontrahenter, og centret er ansvarlig for at udf\xf8re en portef\xf8lje p\xe5 4 milliarder dollars.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35536612",children:"Discussion Service"}),'.\nDen nye NASA-direkt\xf8r blev taget i ed p\xe5 Carl Sagans "Pale Blue Dot", hvilket udl\xf8ste en debat om eds effektivitet, betydningen af hellige tekster, personlige v\xe6rdier versus religi\xf8se tekster og den sande betydning af personligt ansvar. Nogle h\xe6vder, at det er mere hensigtsm\xe6ssigt at sv\xe6rge p\xe5 en bog, der repr\xe6senterer ens v\xe6rdier, mens andre finder det n\xf8dvendigt at have en repr\xe6sentation af en guddom som garant for eden. Ed har rituelle roller og har v\xe6ret brugt til at forme samfund og historie, men i sidste ende indeholder artiklen ingen nye eller sp\xe6ndende oplysninger for eksperter p\xe5 omr\xe5det.']}),"\n",(0,i.jsx)(r.h2,{id:"intel-foundry-services-og-arm-annoncerer-samarbejde-om-soc-design",children:"Intel Foundry Services og Arm annoncerer samarbejde om SoC-design"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry-arm-announce-multigeneration-collaboration-leading-edge-soc-design.html",children:"Original"}),".\nIntel Foundry Services (IFS) og Arm er blevet enige om et flergenerationssamarbejde for at muligg\xf8re udviklingen af lav-effekt-compute system-on-chips (SoC'er) til mobile enheder og andre industrier. Samarbejdet vil medf\xf8re en kombination af Arms sikre og energieffektive processorer med IFS' produktionskapacitet, der omfatter USA- og EU-baserede kapaciteter, og som vil levere nye banebrydende transistorteknologier til forbedring af str\xf8m og ydeevne p\xe5 Intel 18A-processen. Dette samarbejde vil give mulighed for en mere afbalanceret global forsyningsk\xe6de for st\xf8berikunder, der arbejder med design af mobile SoC'er p\xe5 Arm-baserede CPU-kerner."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35539057",children:"Discussion Service"}),".\nIntel Foundry Services samarbejder med Arm om design af SoC'er og st\xe5r over for konkurrence fra TSMC, der har en tradition for samarbejde med Arm. Discussion Service-brugere diskuterer fordele og ulemper ved Mac Studio og sammenligner den med andre PC-muligheder, med kritik af Mac's begr\xe6nsninger for spil og CAD-software. Artiklen og kommentarerne omhandler alternativer til IOT-enheder og fremstilling, Intels produktion af 2nm-noder og spekulationer om Intels evne til at holde deres l\xf8fter, samtidig med at de anerkender betydningen af str\xf8mforbrug, pris og tr\xe5dl\xf8s kapacitet i udviklingen af IOT-enheder."]}),"\n",(0,i.jsx)(r.h2,{id:"eve-online-spiller-bruger-obskur-regel-til-at-gennemf\xf8re-det-st\xf8rste-kup-i-spillets-historie",children:"EVE Online-spiller bruger obskur regel til at gennemf\xf8re det st\xf8rste kup i spillets historie"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.pcgamer.com/eve-online-player-uses-obscure-rule-to-pull-off-the-biggest-heist-in-the-games-history/",children:"Original"}),'.\nEn EVE Online-spiller har gennemf\xf8rt det st\xf8rste r\xf8veri i spillets historie ved at udnytte "shares-mekanikken", hvilket resulterede i et udbytte p\xe5 over 22.300 dollars i rigtige penge. Dette involverede at tage kontrol over Event Horizon Expeditionaries ved hj\xe6lp af en ren konto, overf\xf8re aktier og fratage virksomhedens tegnebog 130 milliarder ISK og flere skibe, hvilket ansl\xe5s til en samlet v\xe6rdi af byttet p\xe5 2,23 trillioner ISK. Andelssystemet er potentielt for nemt at udnytte, if\xf8lge en Reddit-tr\xe5d fra 2014, og denne strategi er blevet testet f\xf8r.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35533711",children:"Discussion Service"}),".\nEn spiller orkestrerede et vellykket kup i EVE Online, hvilket rejser sp\xf8rgsm\xe5l omkring dets virksomhedsmekanik og spillets udnyttelsesrisici. R\xf8veriet blev set som cool og et h\xf8jdepunkt i spillet, men nogle kritiserer spillets finansielle fokus og mekanik, herunder dets v\xe6rdi af in-game valutaen og dets corporate afstemningssystem."]}),"\n",(0,i.jsx)(r.h2,{id:"virtuelle-tr\xe5de-ankommer-i-jdk-21-og-indleder-en-ny-\xe6ra-for-concurrency",children:"Virtuelle tr\xe5de ankommer i JDK 21 og indleder en ny \xe6ra for concurrency"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.infoq.com/news/2023/04/virtual-threads-arrives-jdk21/",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35535906",children:"Discussion Service"}),".\nJDK 21's virtuelle tr\xe5de reducerer antallet af fysiske tr\xe5de med henblik p\xe5 samtidighed og forenkling af io-intensive applikationer, men der opst\xe5r diskussioner om hukommelsesstyring. Java sammenlignes med Go, og rammer som Spring, Spring Boot og Quarkus giver alternativer til Ruby on Rails, mens debatten om Java versus Go tager hensyn til ydeevne, observerbarhed, korrekthed af typesystemer og interop. Artiklen reflekterer over nichekategorien JVM, og hvordan forskellige implementeringer kan p\xe5virke brugeroplevelsen, med sammenligninger med C# og JetBrains Rider n\xe6vnt."]})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(g,{...e})}):g(e)}}}]);